example_item.example_item_data:
schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
filename = [tempdir(), 'indexed.bin'];
protobuf.write(schema, 'SensorSample', filename, ...
  struct('timestamp_ms', num2cell(int64(1:500))), 'Delimited', true);
info = protobuf.index(filename, 'Step', 64)
C = protobuf.read(schema, 'SensorSample', filename, 'Delimited', true, 'Layout', 'columns', 'Records', [250 252]);
C.timestamp_ms
delete(filename);
delete(info.IndexFile);
